"use client";
import React, { useState, useEffect } from 'react';
import Image from 'next/image'; 
import styles from './Navbar.module.css';
import { Menu, X } from 'lucide-react';

const Navbar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <>
      <div className={`${styles['menu-overlay']} ${isOpen ? styles.active : ''}`} onClick={() => setIsOpen(false)} />
      <nav className={`${styles.navbar} ${scrolled ? styles.scrolled : ''}`}>
        <div className={styles['navbar-container']}>
          <a href="#hero" className={styles['navbar-logo']} onClick={() => setIsOpen(false)}>
            <div className={styles['logo-image-wrapper']}>
               <Image src="/logob.webp" alt="EV Logo" width={32} height={32} className={styles['logo-img']} />
            </div>
            <div className={styles['logo-text']}>
              <span className={styles['brand-name']}>EldarVisual</span>
              <span className={styles['brand-tag']}>WEB STUDIO</span>
            </div>
          </a>
          <div className={styles['desktop-menu']}>
            <a href="#services" className={styles['nav-link']}>Services</a>
            <a href="#process" className={styles['nav-link']}>Process</a>
            <a href="#portfolio" className={styles['nav-link']}>Portfolio</a>
          </div>
          <div className={styles['navbar-cta']}>
            <a href="#contact" className={styles['btn-talk']}>Let's Talk</a>
          </div>
          <div className={styles['mobile-toggle']} onClick={() => setIsOpen(!isOpen)}>
            {isOpen ? <X size={28} /> : <Menu size={28} />}
          </div>
        </div>
        <div className={`${styles['mobile-menu']} ${isOpen ? styles.active : ''}`}>
          <a href="#services" className={styles['mobile-link']} onClick={() => setIsOpen(false)}>Services</a>
          <a href="#process" className={styles['mobile-link']} onClick={() => setIsOpen(false)}>Process</a>
          <a href="#portfolio" className={styles['mobile-link']} onClick={() => setIsOpen(false)}>Portfolio</a>
          <a href="#contact" className={`${styles['mobile-link']} ${styles.highlight}`} onClick={() => setIsOpen(false)}>Let's Talk</a>
        </div>
      </nav>
    </>
  );
};
export default Navbar;