"use client"; 
import React, { useState } from 'react';
import styles from './Contact.module.css';
import { Mail, Phone, Send, CheckCircle, X, ExternalLink } from 'lucide-react';
import { useForm, ValidationError } from '@formspree/react';

const Contact = () => {
  const [state, handleSubmit] = useForm("xlggjajo");
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);
  const [companyType, setCompanyType] = useState(""); 
  const emailAddress = "aviram@eldarvisual.com";

  return (
    <section id="contact" className={styles['contact-section']}>
      <div className={styles['contact-container']}>
        <div className={styles['contact-grid']}>
          <div className={styles['info-side']}>
            <span className={styles['section-label']}>Let's Talk</span>
            <h2 className={styles['contact-headline']}>Build. Revamp.</h2>
            <h2 className={`${styles['contact-headline']} ${styles['highlight-purple']}`}>Manage.</h2>
            <div className={styles['contact-details']}>
              <div className={styles['contact-item']} onClick={() => setIsEmailModalOpen(true)} style={{cursor:'pointer'}}>
                <div className={styles['icon-box']}><Mail size={20} /></div>
                <span className={styles['contact-text']}>{emailAddress}</span>
              </div>
            </div>
          </div>
          <div className={styles['form-wrapper']}>
            {state.succeeded ? (
              <div className={styles['success-message']}>
                <CheckCircle size={48} color="#4ade80" />
                <h3 className={styles['success-title']}>Message Sent!</h3>
              </div>
            ) : (
              <form onSubmit={handleSubmit}>
                <div className={styles['form-group']}>
                  <label className={styles['form-label']}>Full Name</label>
                  <input type="text" name="name" className={styles['form-input']} required />
                </div>
                <div className={styles['form-group']}>
                  <label className={styles['form-label']}>Company Type</label>
                  <select 
                    name="type" 
                    className={styles['form-input']} 
                    value={companyType} 
                    onChange={(e) => setCompanyType(e.target.value)}
                    style={{colorScheme: 'dark'}}
                  >
                    <option value="" disabled>Choose...</option>
                    <option value="startup">Startup</option>
                  </select>
                </div>
                <button type="submit" className={styles['submit-btn']} disabled={state.submitting}>Get My Free Audit</button>
              </form>
            )}
          </div>
        </div>
      </div>
    </section>
  );
};
export default Contact;